namespace RecipeHub.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public int TotalRatings { get; set; }
    public int RatingSum { get; set; }

    public double AverageRating => TotalRatings > 0 ? (double)RatingSum / TotalRatings : 0;
}

public class RecipeCategory
{
    public string Name { get; set; } = string.Empty;
    public string Icon { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<RecipeCategory> _categories =
    [
        new() { Name = "Breakfast", Icon = "🥞", Description = "Start your day right with morning favorites" },
        new() { Name = "Lunch", Icon = "🥗", Description = "Midday meals and light bites" },
        new() { Name = "Dinner", Icon = "🍝", Description = "Hearty evening dishes for the whole family" },
        new() { Name = "Desserts", Icon = "🍰", Description = "Sweet treats and baked goods" },
        new() { Name = "Snacks", Icon = "🍿", Description = "Quick bites between meals" },
        new() { Name = "Drinks", Icon = "🥤", Description = "Refreshing beverages and smoothies" },
    ];

    private readonly List<Recipe> _recipes =
    [
        new()
        {
            Id = 1, Title = "Classic Pancakes", Category = "Breakfast",
            Description = "Fluffy golden pancakes perfect for a weekend morning.",
            Ingredients = ["2 cups flour", "2 eggs", "1½ cups milk", "2 tbsp sugar", "2 tsp baking powder", "¼ tsp salt", "2 tbsp melted butter"],
            Steps = ["Mix dry ingredients in a large bowl.", "Whisk eggs, milk, and melted butter together.", "Combine wet and dry ingredients until just mixed.", "Heat a griddle over medium heat and grease lightly.", "Pour ¼ cup batter per pancake and cook until bubbles form.", "Flip and cook until golden brown."],
            TotalRatings = 12, RatingSum = 53,
        },
        new()
        {
            Id = 2, Title = "Avocado Toast", Category = "Breakfast",
            Description = "Simple, nutritious, and endlessly customizable.",
            Ingredients = ["2 slices sourdough bread", "1 ripe avocado", "1 tbsp lemon juice", "Salt and pepper to taste", "Red pepper flakes (optional)", "1 egg (optional)"],
            Steps = ["Toast the bread until golden and crisp.", "Mash the avocado with lemon juice, salt, and pepper.", "Spread avocado mixture on toast.", "Top with red pepper flakes and a fried egg if desired."],
            TotalRatings = 8, RatingSum = 35,
        },
        new()
        {
            Id = 3, Title = "Caesar Salad", Category = "Lunch",
            Description = "A timeless salad with creamy dressing and crunchy croutons.",
            Ingredients = ["1 head romaine lettuce", "½ cup Caesar dressing", "¼ cup grated Parmesan", "1 cup croutons", "2 grilled chicken breasts (optional)"],
            Steps = ["Wash and chop the romaine lettuce.", "Toss lettuce with Caesar dressing.", "Top with Parmesan and croutons.", "Add sliced grilled chicken if desired.", "Serve immediately."],
            TotalRatings = 6, RatingSum = 25,
        },
        new()
        {
            Id = 4, Title = "Grilled Cheese Sandwich", Category = "Lunch",
            Description = "The ultimate comfort food — crispy, melty, and satisfying.",
            Ingredients = ["2 slices bread", "2 slices cheddar cheese", "1 tbsp butter"],
            Steps = ["Butter one side of each bread slice.", "Place cheese between the unbuttered sides.", "Heat a skillet over medium heat.", "Cook sandwich until golden on each side and cheese is melted."],
            TotalRatings = 10, RatingSum = 44,
        },
        new()
        {
            Id = 5, Title = "Spaghetti Bolognese", Category = "Dinner",
            Description = "A rich and hearty Italian classic everyone loves.",
            Ingredients = ["400g spaghetti", "500g ground beef", "1 onion, diced", "3 cloves garlic, minced", "400g crushed tomatoes", "2 tbsp tomato paste", "1 tsp oregano", "Salt and pepper to taste", "Parmesan for serving"],
            Steps = ["Cook spaghetti according to package directions.", "Brown ground beef in a large pan, then drain excess fat.", "Sauté onion and garlic until soft.", "Add crushed tomatoes, tomato paste, and oregano.", "Simmer sauce for 20 minutes.", "Serve sauce over spaghetti with Parmesan."],
            TotalRatings = 15, RatingSum = 68,
        },
        new()
        {
            Id = 6, Title = "Chicken Stir-Fry", Category = "Dinner",
            Description = "Quick, colorful, and packed with flavor.",
            Ingredients = ["2 chicken breasts, sliced", "2 cups mixed vegetables", "3 tbsp soy sauce", "1 tbsp sesame oil", "1 tbsp cornstarch", "2 cloves garlic, minced", "1 tsp ginger, grated", "Cooked rice for serving"],
            Steps = ["Mix soy sauce, sesame oil, and cornstarch in a bowl.", "Stir-fry chicken in a hot wok until cooked through.", "Remove chicken and stir-fry vegetables for 3 minutes.", "Return chicken to the wok and add sauce.", "Cook until sauce thickens.", "Serve over rice."],
            TotalRatings = 9, RatingSum = 40,
        },
        new()
        {
            Id = 7, Title = "Chocolate Chip Cookies", Category = "Desserts",
            Description = "Chewy, buttery cookies loaded with chocolate chips.",
            Ingredients = ["2¼ cups flour", "1 cup butter, softened", "¾ cup sugar", "¾ cup brown sugar", "2 eggs", "1 tsp vanilla", "1 tsp baking soda", "1 tsp salt", "2 cups chocolate chips"],
            Steps = ["Preheat oven to 375°F (190°C).", "Cream butter and sugars until fluffy.", "Beat in eggs and vanilla.", "Mix in flour, baking soda, and salt.", "Fold in chocolate chips.", "Drop rounded tablespoons onto baking sheets.", "Bake 9–11 minutes until golden."],
            TotalRatings = 20, RatingSum = 95,
        },
        new()
        {
            Id = 8, Title = "Fruit Smoothie", Category = "Drinks",
            Description = "A refreshing blend of fresh fruits and yogurt.",
            Ingredients = ["1 banana", "1 cup mixed berries", "½ cup yogurt", "½ cup orange juice", "1 tbsp honey"],
            Steps = ["Add all ingredients to a blender.", "Blend until smooth.", "Pour into a glass and serve immediately."],
            TotalRatings = 7, RatingSum = 30,
        },
        new()
        {
            Id = 9, Title = "Trail Mix", Category = "Snacks",
            Description = "A crunchy, sweet, and salty mix perfect for on-the-go.",
            Ingredients = ["1 cup almonds", "1 cup cashews", "½ cup dried cranberries", "½ cup raisins", "½ cup chocolate chips", "½ cup sunflower seeds"],
            Steps = ["Combine all ingredients in a large bowl.", "Toss to mix evenly.", "Store in an airtight container."],
            TotalRatings = 5, RatingSum = 21,
        },
    ];

    private int _nextId = 10;

    public List<RecipeCategory> GetCategories() => _categories;

    public List<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipeById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetRecipeById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.TotalRatings++;
            recipe.RatingSum += stars;
        }
    }

    public Recipe AddRecipe(string title, string category, string ingredients, string steps)
    {
        var recipe = new Recipe
        {
            Id = _nextId++,
            Title = title,
            Category = category,
            Description = $"A community-submitted recipe for {title}.",
            Ingredients = ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
            Steps = steps.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
        };
        _recipes.Add(recipe);
        return recipe;
    }
}

