@page "/recipe/{RecipeId:int}"
@using RecipeHub.Services
@inject RecipeService RecipeService

@if (recipe is null)
{
    <PageTitle>Recipe Not Found — RecipeHub</PageTitle>
    <h1>Recipe Not Found</h1>
    <p>Sorry, we couldn't find that recipe.</p>
    <a href="/" class="btn btn-outline-secondary">← Back to Home</a>
}
else
{
    <PageTitle>@recipe.Title — RecipeHub</PageTitle>

    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="category/@recipe.Category">@recipe.Category</a></li>
            <li class="breadcrumb-item active" aria-current="page">@recipe.Title</li>
        </ol>
    </nav>

    <h1>@recipe.Title</h1>
    <p class="lead">@recipe.Description</p>

    <div class="row">
        <div class="col-md-4">
            <div class="card mb-4">
                <div class="card-header"><strong>Ingredients</strong></div>
                <ul class="list-group list-group-flush">
                    @foreach (var ingredient in recipe.Ingredients)
                    {
                        <li class="list-group-item">@ingredient</li>
                    }
                </ul>
            </div>
        </div>

        <div class="col-md-8">
            <h3>Instructions</h3>
            <ol class="list-group list-group-numbered mb-4">
                @foreach (var step in recipe.Steps)
                {
                    <li class="list-group-item">@step</li>
                }
            </ol>
        </div>
    </div>

    <div class="card mb-4">
        <div class="card-body">
            <h5 class="card-title">Rate this Recipe</h5>
            <p class="text-muted mb-2">
                Average: @recipe.AverageRating.ToString("F1") / 5
                (@recipe.TotalRatings @(recipe.TotalRatings == 1 ? "rating" : "ratings"))
            </p>
            <StarRating RecipeId="recipe.Id" />
        </div>
    </div>

    <a href="category/@recipe.Category" class="btn btn-outline-secondary">← Back to @recipe.Category</a>
}

@code {
    [Parameter] public int RecipeId { get; set; }
    private RecipeHub.Models.Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetRecipeById(RecipeId);
    }
}

@rendermode InteractiveServer
@using RecipeHub.Services
@inject RecipeService RecipeService

<div class="d-inline-block" style="font-size: 1.5rem; cursor: pointer;">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span @onclick="() => Rate(star)"
              @onmouseover="() => hoverRating = star"
              @onmouseout="() => hoverRating = 0"
              style="color: @(star <= DisplayRating ? "#ffc107" : "#e0e0e0"); transition: color 0.15s;">
            ★
        </span>
    }
</div>

@if (submitted)
{
    <div class="text-success mt-1">
        <small>Thanks! You rated this @submittedRating out of 5.</small>
    </div>
}

@code {
    [Parameter] public int RecipeId { get; set; }

    private int hoverRating;
    private int selectedRating;
    private bool submitted;
    private int submittedRating;

    private int DisplayRating => hoverRating > 0 ? hoverRating : selectedRating;

    private void Rate(int stars)
    {
        selectedRating = stars;
        submittedRating = stars;
        submitted = true;
        RecipeService.AddRating(RecipeId, stars);
    }
}

